<?php    namespace ADMIN\AdminBundle\Entity;    use Doctrine\ORM\EntityRepository;        /**
     * CnrtPersonaRepository
     *
     * This class was generated by the Doctrine ORM. Add your own custom
     * repository methods below.
    */
    class CnrtPersonaRepository extends EntityRepository    {            public function leerCNRTPersonas($parameters){                        $sSql = "";            $sMensaje = "";            $date = new \DateTime();                                    $sSql .= " select p";            $sSql .= "        from ADMINAdminBundle:CnrtPersona p";            $sSql .= " WHERE 1 = 1 ";                        if( isset( $parameters['txtNroDocumento']) && $parameters["txtNroDocumento"]!="" ){                $sSql .= "        and p.numeroDocumento = '" . $parameters["txtNroDocumento"] . "'" ;            }                        if( isset( $parameters['lstEstados']) && $parameters["lstEstados"]!="" ){                $sSql .= "        and p.estado = " . $parameters["lstEstados"] . "" ;            }                        if( isset( $parameters['txtApellido']) && $parameters["txtApellido"]!="" ){                //  REEMPLAZO LOS CARACTERES COMILLA SIMPLE Y DOBLE, PARA EVITAR QUE ROMPAN EL STRING SQL                $sTxt = "";                $sTxt = $parameters["txtApellido"];                $sTxt = str_replace("'", "", $sTxt);                $sTxt = str_replace("\"", "", $sTxt);                                $sSql .= "        and p.apellido like '%" . strtoupper($sTxt) . "%'" ;            }            if( isset( $parameters['txtNombre']) && $parameters["txtNombre"]!="" ){                //  REEMPLAZO LOS CARACTERES COMILLA SIMPLE Y DOBLE, PARA EVITAR QUE ROMPAN EL STRING SQL                $sTxt = "";                $sTxt = $parameters["txtNombre"];                $sTxt = str_replace("'", "", $sTxt);                $sTxt = str_replace("\"", "", $sTxt);                $sSql .= "        and p.nombre like '%" . strtoupper( $sTxt ). "%'" ;            }                                    if(isset($parameters["dtfechaDesde"]) && isset($parameters["dtfechaHasta"]) ){                if($parameters["dtfechaDesde"] != "" && $parameters["dtfechaHasta"] != ""){                    $sSql .= "        and p.fechaConsulta between '" . $parameters["dtfechaDesde"] . " 00:00:00" . "' and '" . $parameters["dtfechaHasta"] ." 23:59:59" . "'" ;                }            }                        if(isset($parameters["txtidCnrt"]) ){                if($parameters["txtidCnrt"] != "" ){                    $sSql .= "        and p.idPasajero = " . $parameters["txtidCnrt"];                }            }                        $sSql .= " order by p.idPasajero desc ";                        $query = $this->getEntityManager()->createQuery( $sSql  );            $oRes = $query->getResult();                        return $oRes;        }                        public function leerPersonasFiltro($parameters){                        $sSql = "";            $sMensaje = "";            $date = new \DateTime();                        $sSql .= " select p ";            $sSql .= "        from ADMINAdminBundle:CnrtPersona p";            $sSql .= " WHERE 1 = 1 ";                        if( isset( $parameters['txtIdPasajero']) && $parameters["txtIdPasajero"]!="" && is_numeric(trim($parameters["txtIdPasajero"])) ){                $sSql .= "        and p.idPasajero = " . trim($parameters["txtIdPasajero"]) ;            }                        if( isset( $parameters['txtNroDocumento']) && $parameters["txtNroDocumento"]!="" ){                $sSql .= "        and p.numeroDocumento = '" . $parameters["txtNroDocumento"] . "'" ;            }                        if( isset( $parameters['lstEstados']) && $parameters["lstEstados"]!="" ){                $sSql .= "        and p.estado = " . $parameters["lstEstados"] . "" ;            }                        if( isset( $parameters['txtApellido']) && $parameters["txtApellido"]!="" ){                //  REEMPLAZO LOS CARACTERES COMILLA SIMPLE Y DOBLE, PARA EVITAR QUE ROMPAN EL STRING SQL                $sTxt = "";                $sTxt = $parameters["txtApellido"];                $sTxt = str_replace("'", "", $sTxt);                $sTxt = str_replace("\"", "", $sTxt);                                $sSql .= "        and p.apellido like '%" . strtoupper($sTxt) . "%'" ;            }                        if( isset( $parameters['txtNombre']) && $parameters["txtNombre"]!="" ){                //  REEMPLAZO LOS CARACTERES COMILLA SIMPLE Y DOBLE, PARA EVITAR QUE ROMPAN EL STRING SQL                $sTxt = "";                $sTxt = $parameters["txtNombre"];                $sTxt = str_replace("'", "", $sTxt);                $sTxt = str_replace("\"", "", $sTxt);                $sSql .= "        and p.nombre like '%" . strtoupper( $sTxt ). "%'" ;            }                        if(isset($parameters["dtfechaDesde"])){                if($parameters["dtfechaDesde"] != ""){                    $sSql .= "        and p.fechaConsulta > '" . $parameters["dtfechaDesde"] . " 00:00:00" . "'" ;                }            }                        if(isset($parameters["dtfechaHasta"]) ){                if($parameters["dtfechaHasta"] != ""){                    $sSql .= "        and p.fechaConsulta < '" . $parameters["dtfechaHasta"] ." 23:59:59" . "'" ;                }            }                        if( isset( $parameters['lstResultado']) && $parameters["lstResultado"]!="" ){                $sSql .= "        and p.resultado = " . $parameters["lstResultado"] . "" ;            }                        $sSql .= " order by p.idPasajero desc";                        $query = $this->getEntityManager()->createQuery( $sSql  );                        return $query;        }                        public function leerCNRTPersonasId($id){                        $sSql = "";            $sMensaje = "";            $date = new \DateTime();                        $sSql .= " select p";            $sSql .= "        from ADMINAdminBundle:CnrtPersona p";            $sSql .= " WHERE 1 = 1 ";            $sSql .= " and p.id = " . $id;                        $query      = $this->getEntityManager()->createQuery( $sSql  );            $oRes       = $query->getResult();            $retorno    = [];            $sFechaIni  = "";            $sFechaFin  = "";            $sfechaCons = "";            foreach( $oRes as $fila ){                if($fila->getFechaInicio()!=''){                    $sFechaIni = substr( $fila->getFechaInicio(), 0, 2)."/".substr( $fila->getFechaInicio(), 3, 2)."/".substr( $fila->getFechaInicio(), 6, 4) . " ". substr( $fila->getFechaInicio(), 11 );                }else{                    $sFechaIni = '&nbsp;';                }                if($fila->getFechaFin()!=''){                    $sFechaFin = substr( $fila->getFechaFin(), 0, 2)."/".substr( $fila->getFechaFin(), 3, 2)."/".substr( $fila->getFechaFin(), 6, 4) . " ". substr( $fila->getFechaFin(), 11 );                }else{                    $sFechaFin = '&nbsp;';                }                                    $sDetalle = stream_get_contents( $fila->getRespuestaDetails() );                $retorno["ID"]                = $fila->getId();                $retorno["ID_PASAJERO"]       = $fila->getIdPasajero();                $retorno["FECHA_NACIMIENTO"]  = $fila->getFechaNacimiento();                $retorno["FECHA_CONSULTA"]    = $fila->getFechaConsulta()->format('d/m/Y H:i:s');                $retorno["ESTADO"]            = $fila->getEstado();                $retorno["RESULTADO"]         = $fila->getResultado();                 $retorno["RESPUESTA_DETAILS"] = $sDetalle;                $retorno["APELLIDO"]          = $fila->getApellido();                $retorno["NOMBRE"]            = $fila->getNombre();                $retorno["NUMERO_DOCUMENTO"]  = $fila->getNumeroDocumento();                $retorno["SEXO"]              = $fila->getSexo();                $retorno["FECHA_INICIO"]      = $sFechaIni;                $retorno["FECHA_FIN"]         = $sFechaFin;                $retorno["ORIGEN"]            = $fila->getOrigen();                $retorno["PCIA_ORIGEN"]       = $fila->getPciaOrigen();                $retorno["DESTINO"]           = $fila->getDestino();                $retorno["PCIA_DESTINO"]      = $fila->getPciaDestino();                $retorno["NRO_BUTACA"]        = $fila->getNroButaca();                $retorno["DOMINIO"]           = $fila->getDominio();                $retorno["NRO_EMPRESA"]       = $fila->getNroEmpresa();                $retorno["DESC_EMPRESA"]      = $fila->getDescEmpresa();                $retorno["OBSERVACIONES"]     = $fila->getObservaciones();                $retorno["FECHA_CANCELACION"] = ($fila->getFechaCancelacion()!=null)?$fila->getFechaCancelacion()->format('d/m/Y H:i:s'):'';            }                        $retorno = json_encode($retorno);            return $retorno;        }                public function leerEstados(){            //  Estado de verificacion contra el servicio de Interpol. (0-PENDIENTE, 1-VERIFICADO, 2-INEXISTENTE RENAPER, 3-ERROR COMUNICACION RENAPER, 4-ERROR COMUNICACION INTERPOL, 5-ERROR COMUNICACION IDGE, 6-INEXISTENTE IDGE).            $retorno = [                                                ["CODIGO" => "0", "DESCRIPCION" => "PENDIENTE"],                        ["CODIGO" => "1", "DESCRIPCION" => "VERIFICADO"],                        ["CODIGO" => "2", "DESCRIPCION" => "INEXISTENTE RENAPER"],                        ["CODIGO" => "3", "DESCRIPCION" => "ERROR COMUNICACION RENAPER"],                        ["CODIGO" => "4", "DESCRIPCION" => "ERROR COMUNICACION INTERPOL"],                        ["CODIGO" => "5", "DESCRIPCION" => "ERROR COMUNICACION IDGE"],                        ["CODIGO" => "6", "DESCRIPCION" => "INEXISTENTE IDGE"],                        ["CODIGO" => "7", "DESCRIPCION" => "ESTADO NO DEFINIDO"]                       ];            return $retorno;        }            public function getErrores24(){            $date = new \DateTime();            $date->modify('-1 day');                        $sSql = " SELECT p FROM ADMINAdminBundle:CnrtPersona p";            $sSql .= " WHERE p.estado != 1" ;            $sSql .= " AND p.fechaConsulta >= TO_DATE('".$date->format('d/m/Y H:i:s')."','dd/mm/yyyy hh24:mi:ss')" ;            $sSql .= " ORDER BY p.id";                        $query = $this->getEntityManager()->createQuery( $sSql  );                        return $query->getResult();        }                        public function getAuditoria($id,$filter){                        $sSql = "SELECT a FROM ADMINAdminBundle:AuditoriaCnrtPersona a LEFT JOIN a.usuAlta u WHERE a.cnrtPersona = ".$id;                        if(!empty($filter['txtUsuario'])){                if($filter['txtUsuario'] != ""){                    $sSql .= " and upper( u.usuario ) like upper( '%".$filter['txtUsuario']."%' )";                }            }                        if(!empty($filter["fDesde"])){                $sSql .= " and a.fecAlta >= to_date( '".$filter["fDesde"]."', 'DD/MM/YYYY HH24:MI:SS' )";            }                        if(!empty($filter["fHasta"])){                $sSql .= " and a.fecAlta <= to_date( '".$filter["fHasta"]."', 'DD/MM/YYYY HH24:MI:SS' )";            }                        $sSql .= " ORDER BY a.id DESC";                        $query = $this->getEntityManager()->createQuery( $sSql  );                        return $query;        }                public function getMaxFechaConsulta(){                        $sSql = "SELECT max(a.fechaConsulta) maxFechaConsulta FROM ADMINAdminBundle:CnrtPersona a";                        $query = $this->getEntityManager()->createQuery( $sSql  );                        return $query->getResult();        }    
    }            